                $display("  Got:      StateData=%h, StateDrop=%b, StateIdle=%b, StatePreamble=%b, StateSFD=%b",
                         StateData, StateDrop, StateIdle, StatePreamble, StateSFD);
                fail_count = fail_count + 1;
            end
        end
    endtask

