module jt51_timer_tb;

    // Testbench signals (sequential circuit)
    reg clk;
    reg clr_flag;
    reg clr_run;
    reg load;
    reg rst;
    reg set_run;
    reg [9:0] start_value;
    wire flag;
    wire overflow;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    jt51_timer dut (
        .clk(clk),
        .clr_flag(clr_flag),
        .clr_run(clr_run),
        .load(load),
        .rst(rst),
        .set_run(set_run),
        .start_value(start_value),
        .flag(flag),
        .overflow(overflow)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            rst = 1;
            clr_flag = 0;
            clr_run = 0;
            load = 0;
            set_run = 0;
            start_value = 0;
            @(posedge clk);
            #1;
            rst = 0;
            @(posedge clk);
            #1;
        end
        endtask
    task testcase001;

        begin
            test_num = 1;
            $display("\nTestcase %0d: Basic Reset State", test_num);
            reset_dut();

            #1;


            check_outputs(1'b0, 1'b0);
        end
        endtask

    task testcase002;

        begin
            test_num = 2;
            $display("\nTestcase %0d: Load Value without Running", test_num);
            reset_dut();

            start_value = 10'h3FF;
            load = 1;
            @(posedge clk);
            #1;
            load = 0;

            repeat(10) @(posedge clk);

            #1;


            check_outputs(1'b0, 1'b0);
        end
        endtask

    task testcase003;

        begin
            test_num = 3;
            $display("\nTestcase %0d: Simple Overflow", test_num);
            reset_dut();


            start_value = 10'h3FE;
            load = 1;
            @(posedge clk);
            #1;
            load = 0;


            set_run = 1;
            @(posedge clk);
            #1;
            set_run = 0;



            repeat(50) begin
                @(posedge clk);
                if (flag == 1'b1) break;
            end
            #1;


            #1;



            check_outputs(1'b1, overflow);
