                 (color_depth_i == 2'b01) && (mem_lsb_i[0] == 1'b0)  ? {mem_i[31:16]} : 
                 (color_depth_i == 2'b01) && (mem_lsb_i[0] == 1'b1)  ? {mem_i[15:0]}  : 
