module sysgen_logical_2d2e86ecb2 (
  input [(1 - 1):0] d0,
  input [(1 - 1):0] d1,
  output [(1 - 1):0] y,
  input clk,
  input ce,
  input clr);
  reg [(1 - 1):0] d0_1_24;
  reg [(1 - 1):0] d1_1_27;
