  initial begin
    d0_1_24 = 1'b0;
    d1_1_27 = 1'b0;
  end

  always @(posedge clk) begin
    if (clr) begin
      d0_1_24 <= 1'b0;
      d1_1_27 <= 1'b0;
    end
  end

endmodule

